import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"普通攻击","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills-normal-attack.md","filePath":"guide/skills-normal-attack.md","lastUpdated":1792083729000}'),l={name:"guide/skills-normal-attack.md"};function s(n,a,c,i,d,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="普通攻击" tabindex="-1">普通攻击 <a class="header-anchor" href="#普通攻击" aria-label="Permalink to &quot;普通攻击&quot;">​</a></h1><p>简称<strong>普攻</strong>。这是最常见的攻击方式，也是一种<strong>特殊的技能类型</strong>，它基于角色的总攻击力来造成物理伤害。</p><h2 id="等级" tabindex="-1">等级 <a class="header-anchor" href="#等级" aria-label="Permalink to &quot;等级&quot;">​</a></h2><p>角色初始普通攻击等级为 <strong>1 级</strong>，可以升级，最高 <strong>8 级</strong>。</p><p>升级所需的角色等级：<code>8 / 16 / 24 / 32 / 40 / 48 / 56</code>。</p><h2 id="附魔" tabindex="-1">附魔 <a class="header-anchor" href="#附魔" aria-label="Permalink to &quot;附魔&quot;">​</a></h2><p><strong>普通攻击附魔</strong>：将普通攻击转为魔法伤害。</p><ul><li>装备的武器类型为<strong>法杖或法器</strong>时，自动获得附魔</li><li><strong>技能特效</strong>也可以修改普通攻击的伤害类型</li><li>若没有指定附魔的类型，则默认为角色的<strong>魔法属性类型</strong>（<code>MagicType</code>）</li></ul><h2 id="射程与目标" tabindex="-1">射程与目标 <a class="header-anchor" href="#射程与目标" aria-label="Permalink to &quot;射程与目标&quot;">​</a></h2><p><code>NormalAttack.AttackRange</code> 默认跟随角色的 <code>ATR</code>，也可显式设置独立射程（最小为 1）。<code>AttackAnywhere</code> 或任一全选标志使攻击使用全图射程，附魔本身不改变射程。</p><p>全选敌方和友方可同时开启，取合法目标并集，保留可选类型、免疫和过滤限制；自身还需全选友方及 <code>CanSelectSelf</code>。全选优先于目标数量和扩散，详见 <a href="./skills.html#全选目标">全选目标</a>及 <a href="./../api/NormalAttack.html">NormalAttack API</a>。</p>',11)])])}const m=t(l,[["render",s]]);export{g as __pageData,m as default};
